head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/digital_recv_common.js");
scwin.vScrenID = "ULDSTF70005.xml"; //화면ID

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vAcptNo = "";
scwin.clickListBzTpCd = ""; //상장업무구분코드 (그리드 로우 클릭시 상장업무구분코드를 획득함)
scwin.clickBzProcsNo = ""; //업무처리번호 (클릭된)

scwin.readOnlyYn = "N";
scwin.procJob = "";
scwin.logicPackYn = "Y";
scwin.clickIsuCd = ""; //종목코드(클릭된)
scwin.clickAddIsuRnd = ""; //추가상장차수(클릭된)
scwin.clickListEtpProdTpCd = ""; // ETP상품구분코드(클릭된)
scwin.vListInit = true;
scwin.logicPackYn = "Y";
scwin.clickListApplntIsurNm = ""; //상장신청인(클릭된)
scwin.clickIsuAbbrv = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //종목명(클릭된)

/********************************************** 
 * 함수명 : fn_list_sync()
 * 설명    :  상장신청접수 에 대한 목록 조회
 **********************************************/
scwin.fn_list_sync = function() {
    var v_listBzTpCd = "";
    scwin.vListInit = false; //처음 화면 로딩시 두 번 리스트 조회 안타게 하기 위함.

    // alert("txb_ISUR_CD.value:"+ txb_ISUR_CD.value);

    if (MaxTab_01.getSelectedTabIndex() == 1) {
        //  디지털증권 예비심사 청구		
        v_listBzTpCd = "780";
        var url = "/digital/DigitalListedRcv.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listDigitalPrelmInvstRcv";
        url += "&inputMessageId=DIGITAL_LISTEDRCV_SEARCH_OUT";
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        // 디지털증권 신규상장 청구
        v_listBzTpCd = "781";
        var url = "/digital/DigitalListedRcv.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listDigitalReceiptRcvFor781";
        url += "&inputMessageId=DIGITAL_LISTEDRCV_SEARCH_OUT";
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        // 디지털증권 추가상장 예비심사
        v_listBzTpCd = "783";
        var url = "/digital/DigitalListedRcv.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listDigitalAddPrelmInvstRcv";
        url += "&inputMessageId=DIGITAL_LISTEDRCV_SEARCH_OUT";
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        dts_List_3.DataID = encodeURI(url);
        dts_List_3.Reset();
        $c.cm.ShowWin(grd_List_3);
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        // 디지털증권 추가상장 청구
        v_listBzTpCd = "784";
        var url = "/digital/DigitalListedRcv.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listDigitalReceiptRcvFor784";
        url += "&inputMessageId=DIGITAL_LISTEDRCV_SEARCH_OUT";
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        dts_List_4.DataID = encodeURI(url);
        dts_List_4.Reset();
        $c.cm.ShowWin(grd_List_4);
    }
};




/********************************************** 
 * 함수명 : fn_setBzProcsNo()
 * 설명    : (신규접수)클릭된 그리드에 대한 업무처리번호 획득
 **********************************************/
scwin.fn_setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(eval(obj), "BZ_PROCS_NO");
    scwin.clickListBzTpCd = dtsObj.getCellData(eval(obj), "LIST_BZ_TP_CD");
    scwin.clickListApplntIsurNm = dtsObj.getCellData(eval(obj), "LIST_APPLNT_ISUR_NM"); //상장신청인
    scwin.clickIsuCd = dtsObj.getCellData(eval(obj), "ISU_CD"); //종콕코드
    scwin.clickIsuAbbrv = dtsObj.getCellData(eval(obj), "ISU_ABBRV"); //종목약명

};


/********************************************** 
 * 함수명 : fn_OpenNewWinForDgse()
 * 설명    :  상장신청접수 에 대한 상세 팝업조회
 **********************************************/
scwin.fn_OpenNewWinForDgse = async function(row, dtsObj) {
    scwin.fn_setBzProcsNo(row, dtsObj);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        await $c.frame.CreateDialogFrame("DGSE_NLIST", "/digital/ULDSTF70006.gfm", "상장예비심사", 10, 10, 1060, 820, "window");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        await $c.frame.CreateDialogFrame("DGSE_NLIST", "/digital/ULDSTF70007.gfm", "신규상장", 10, 10, 1080, 820, "window");
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        await $c.frame.CreateDialogFrame("DGSE_LNLIST", "/digital/ULDSTF70008.gfm", "추가상장예비심사", 10, 10, 1070, 820, "window");
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        await $c.frame.CreateDialogFrame("DGSE_LALIST", "/digital/ULDSTF70009.gfm", "추가상장", 10, 10, 1060, 820, "window");
    }
};



// 상장신청인 선택 팝업호출용
scwin.fn_SetParIsur2 = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM.setValue(arrPar[0].ISUR_NM);
        scwin.fn_list_sync();
    }
};
scwin.fn_GetParIsur2 = function(arrPar) {
    arrPar[0] = "lds.stf.digital.select.isurcdappl.condition";
    return arrPar.length;
};


/********************************************** 
 * 함수명 : fn_ExcelDown()
 * 설명    : 정보를 excel로 다운 받는다.
 **********************************************/
scwin.fn_ExcelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "상장예비심사", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "신규상장", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        $c.data.downloadGridViewExcel(grd_List_3, "추가상장예비심사", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        $c.data.downloadGridViewExcel(grd_List_4, "추가상장", "", "8");
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.img_IsuSearch_onclick = function() {
    scwin.fn_SetPar = fn_SetParIsur2;
    scwin.fn_GetPar = fn_GetParIsur2;
    $c.lcd.fn_PopFindDigitalIsurAppl();
};
scwin.gform_onload = function() {
    MaxTab_01.setSelectedTabIndex(1);
    scwin.fn_list_sync();
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.dts_List_3_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_3);
};
scwin.dts_List_4_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_4);
};
scwin.grd_List_1_OnDblClick = function(row, colid) {
    //신규상장접수 > Grid Row Click
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWinForDgse(row, dts_List_1);
    }
};
scwin.grd_List_2_OnDblClick = function(row, colid) {
    //신규상장접수 > Grid Row Click
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWinForDgse(row, dts_List_2);
    }
};
scwin.grd_List_3_OnDblClick = function(row, colid) {
    //신규상장접수 > Grid Row Click
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWinForDgse(row, dts_List_3);
    }
};
scwin.grd_List_4_OnDblClick = function(row, colid) {
    //신규상장접수 > Grid Row Click
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWinForDgse(row, dts_List_4);
    }
};
scwin.txb_ISUR_CD_onchange = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD).length == 0) {
        txb_ISUR_NM.setValue("");
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    //Download excel data
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
